  'bulk_1788533434677_141_0f9e', '-P0gtN5LKh3VGGM07Vl8', 'bulk_1788533434677_141', 'Yasser Attia', '', 'شركة ابناء الصاوي لتجارة المواد الغذائية بالجملة', 'shrka-abna-alsawy-ltgara-almwad-alghzayya-balgmla', 4, 'جودة العمل عالية ومطابقة لما تم الاتفاق عليه، أنصح بتجربة شركة ابناء الصاوي لتجارة المواد الغذائية بالجملة.', 1, 0, 1784364949918, 1784364949918
);
